const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Execute the swap in a transaction
const txn = db.transaction(() => {
    // 1. Update order status to 'pending (item modified)'
    db.prepare(\"UPDATE orders SET status = 'pending (item modified)' WHERE order_id = '#W4705780'\").run();

    // 2. Update the order item: swap item_id, price, and options
    db.prepare(\"UPDATE order_items SET item_id = '2364909101', unit_price = 53.89, options = '{\\\"color\\\": \\\"Olive\\\", \\\"size\\\": \\\"M\\\"}' WHERE order_id = '#W4705780' AND item_id = '9716794911'\").run();

    // 3. Add payment record for the price difference (\$1.10)
    db.prepare(\"INSERT INTO order_payments (order_id, transaction_type, amount, payment_method_id, created_at) VALUES ('#W4705780', 'payment', 1.10, 'credit_card_5360334', datetime('now'))\").run();
});

txn();

// Verify the changes
const order = db.prepare(\"SELECT order_id, status FROM orders WHERE order_id = '#W4705780'\").get();
const items = db.prepare(\"SELECT item_id, name, unit_price, options FROM order_items WHERE order_id = '#W4705780'\").all();
const payments = db.prepare(\"SELECT * FROM order_payments WHERE order_id = '#W4705780'\").all();

console.log('Updated order:', JSON.stringify(order, null, 2));
console.log('Items:', JSON.stringify(items, null, 2));
console.log('Payments:', JSON.stringify(payments, null, 2));
" 2>&1

